// PowerAtlasMx v2 service worker, scope /v2/.
//  - One release = one cache (SHELL). install precaches the WHOLE shell (all-or-nothing, list generated by
//    tools/precache-manifest.mjs); files are served cache-first within the release, so module versions never mix.
//  - A new worker waits; it takes over when the page is reloaded at a safe point (main.js asks it to skip waiting on load).
//  - Data JSON: network first, the cached copy is only an offline fallback.
//  - v1's worker deletes every cache that does not start with its own VERSION (including ours): if that happens the shell is
//    re-filled from the network on the next online visit, and offline navigations fall back to an inline page, never undefined.
// Bump VERSION on every release that changes the shell.
const VERSION = 'v2-m9-2-ec16a071';
const SHELL = `v2-shell-${VERSION}`;
const DATA = 'v2-data';
// Data cache bound: the core JSON (index, analysis, series, profiles, per-config scalars: about 21 MB raw) is pinned; per-variant files
// (variants/*.json about 4.5 MB, variant_extra about 0.25 MB) are evictable, oldest first, at most DATA_VARIANTS entries (about 25 MB worst case).
const DATA_VARIANTS = 5;
// Daily series (data/solar_v2/daily/, 38 area files and one file per node): fetched on demand, about 100 KB each, at most DATA_DAILY kept (about 1.2 MB), never precached.
const DATA_DAILY = 12;
importScripts('sw-strategy.js', 'precache.js');

const OFFLINE_HTML = '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Offline · PowerAtlasMx</title>'
  + '<body style="margin:0;min-height:100vh;display:grid;place-items:center;background:#0A0A0A;color:#F0E8D2;font:450 16px/1.5 system-ui,sans-serif;padding:24px"><main style="max-width:420px">'
  + '<h1 style="font-weight:450;letter-spacing:-.04em;margin:0 0 8px">You are offline</h1><p style="color:#C3BEA9">PowerAtlasMx could not reach the server and this page is not stored on this device yet. Open it again when you are back online.</p></main></body></html>';
const inlineOffline = () => new Response(OFFLINE_HTML, { status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8' } });

const precache = () => caches.open(SHELL).then((c) => c.addAll(self.PRECACHE));

self.addEventListener('install', (e) => { e.waitUntil(precache()); });
self.addEventListener('activate', (e) => {
  const preload = self.registration.navigationPreload ? self.registration.navigationPreload.enable().catch(() => null) : null;
  e.waitUntil(Promise.all([preload, caches.keys().then((ks) => Promise.all(self.swStrategy.staleCaches(ks, SHELL, DATA).map((k) => caches.delete(k))))]));
});
self.addEventListener('message', (e) => { if (e.data === 'SKIP_WAITING') self.skipWaiting(); });

const store = (name, req, res) => self.swStrategy.storeResponse(caches, name, req, res, console.warn.bind(console));

const handlers = {
  navigate: (req, e) => caches.open(SHELL).then((c) => c.match('./')).then((hit) => {
    if (hit) return hit;
    // shell missing (never installed fully, or removed by v1's worker): go to the network and re-fill it
    return Promise.resolve(e.preloadResponse).then((p) => p || fetch(req)).then((r) => { if (r && r.ok) e.waitUntil(precache().catch(() => null)); return r; })
      .catch(() => inlineOffline());
  }),
  static: (req, e) => caches.open(SHELL).then((c) => c.match(req)).then((hit) => {
    if (hit) return hit;
    return fetch(req).then((r) => { e.waitUntil(store(SHELL, req, r)); return r; }).catch(() => Response.error());
  }),
  data: (req, e) => fetch(req).then((r) => { e.waitUntil(store(DATA, req, r).then(() => Promise.all([self.swStrategy.trimCache(caches, DATA, DATA_VARIANTS, self.swStrategy.evictableUrl), self.swStrategy.trimCache(caches, DATA, DATA_DAILY, self.swStrategy.dailyUrl)]))); return r; }).catch(() => caches.open(DATA).then((c) => c.match(req)).then((h) => h || Response.error())),
};

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;
  const s = self.swStrategy.strategyFor(url.pathname, req.mode);
  if (s === 'bypass') return;
  if (req.headers.has('range')) return; // media-style partial requests are never cached
  e.respondWith(handlers[s](req, e));
});
